import{f as e,j as t,m as n}from"./runtime-core.esm-bundler-DBPRRnSd.js";import{t as r}from"./plugin-vue_export-helper-CDQIAITX.js";var i=JSON.parse(`{"path":"/notes/%E9%9D%A2%E8%AF%95/%E7%9C%9F%E5%AE%9E%E9%9D%A2%E7%BB%8F/%E6%B6%A6%E5%92%8C%E8%BD%AF%E4%BB%B6/","title":"润和软件 | notes","lang":"zh-CN","frontmatter":{"title":"润和软件","createTime":"2026/04/04 23:28:20","permalink":"/notes/面试/真实面经/润和软件/","description":"介绍 人力外包到长飞光纤 实施+后端+前端 设计模式 门面模式 提供一个统一的接口 如果系统需要暴露3个接口给别人系统使用，可以考虑封装成一个接口 比如出入库信息，生产工单等 建造者模式 复杂对象的构建，一步一步的构建 比如生成报表对象， 需要一个报表信息对象、生成器、生成器上下文； 生成器上下文负责查询数据，填充到生成器上下文中，生成器负责处理数据成...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"润和软件\\",\\"image\\":[\\"\\"],\\"dateModified\\":\\"2026-06-25T07:15:35.000Z\\",\\"author\\":[]}"],["meta",{"property":"og:url","content":"http://xiaofei.site/notes/%E9%9D%A2%E8%AF%95/%E7%9C%9F%E5%AE%9E%E9%9D%A2%E7%BB%8F/%E6%B6%A6%E5%92%8C%E8%BD%AF%E4%BB%B6/"}],["meta",{"property":"og:site_name","content":"计算机知识杂货铺"}],["meta",{"property":"og:title","content":"润和软件"}],["meta",{"property":"og:description","content":"介绍 人力外包到长飞光纤 实施+后端+前端 设计模式 门面模式 提供一个统一的接口 如果系统需要暴露3个接口给别人系统使用，可以考虑封装成一个接口 比如出入库信息，生产工单等 建造者模式 复杂对象的构建，一步一步的构建 比如生成报表对象， 需要一个报表信息对象、生成器、生成器上下文； 生成器上下文负责查询数据，填充到生成器上下文中，生成器负责处理数据成..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-06-25T07:15:35.000Z"}],["meta",{"property":"article:modified_time","content":"2026-06-25T07:15:35.000Z"}]]},"readingTime":{"minutes":2.2,"words":659},"git":{"createdTime":1775331561000,"updatedTime":1782371735000,"contributors":[{"name":"xiaofei","username":"xiaofei","email":"tu_aofei@163.com","commits":1,"avatar":"https://avatars.githubusercontent.com/u/49927991?s=96&v=4","url":"https://github.com/731016"},{"name":"731016","username":"731016","email":"xiaofei00152@gmail.com","commits":1,"avatar":"https://avatars.githubusercontent.com/731016?v=4","url":"https://github.com/731016"}],"changelog":[{"hash":"6226c1c3cfce235348f612b9ec8a011caac82791","time":1782371735000,"email":"xiaofei00152@gmail.com","author":"731016","message":"更新侧边栏配置和图标"},{"hash":"fb8bc3afbb338138170b503192cbdb88a45075bd","time":1775331561000,"email":"tu_aofei@163.com","author":"xiaofei","message":"更新为vuepress"}]},"autoDesc":true,"filePathRelative":"notes/面试/真实面经/润和软件.md","headers":[],"bulletin":true}`),a={name:`润和软件.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<h2 id="介绍" tabindex="-1"><a class="header-anchor" href="#介绍"><span>介绍</span></a></h2><p>人力外包到长飞光纤</p><p>实施+后端+前端</p><h2 id="设计模式" tabindex="-1"><a class="header-anchor" href="#设计模式"><span>设计模式</span></a></h2><h3 id="门面模式" tabindex="-1"><a class="header-anchor" href="#门面模式"><span><strong>门面模式</strong></span></a></h3><p>提供一个统一的接口</p><p>如果系统需要暴露3个接口给别人系统使用，可以考虑封装成一个接口</p><p>比如出入库信息，生产工单等</p><h3 id="建造者模式" tabindex="-1"><a class="header-anchor" href="#建造者模式"><span>建造者模式</span></a></h3><p>复杂对象的构建，一步一步的构建</p><p>比如生成报表对象，</p><p>需要一个报表信息对象、生成器、生成器上下文；</p><p>生成器上下文负责查询数据，填充到生成器上下文中，生成器负责处理数据成为报表数据到报表信息对象</p><h2 id="主要介绍业务" tabindex="-1"><a class="header-anchor" href="#主要介绍业务"><span><strong>主要介绍业务</strong></span></a></h2><h3 id="生产工单" tabindex="-1"><a class="header-anchor" href="#生产工单"><span>生产工单</span></a></h3><p>车间人员下发生产指令到底层数采系统（信息包括牌号等信息），数采系统解析后返回工单号，机台，批次等信息，mes生成生产工单；</p><p>产量分为数采产量和车间人员填写的实际的产量，可能有抽检或其他用途和数采系统有出入</p><p>工单状态通过数采系统反馈</p><p>由车间人员通过每个牌号的产量确认单填写，可能有各个工序的不同的数量</p><h3 id="出入库" tabindex="-1"><a class="header-anchor" href="#出入库"><span>出入库</span></a></h3><p>生产牌号需要的物料的库存管理，主要负责专注于物料从收货-&gt;检验-&gt;出库投入生产这个流程的控制 收货需要创建在MES创建入库单，由WMS物流管理平台发送数据到MES，进行收货；MES校验货物信息（货物数量）后，根据物料的检验标准创建报检单进行抽检，抽检合格后入库</p><h3 id="检验工单" tabindex="-1"><a class="header-anchor" href="#检验工单"><span>检验工单</span></a></h3><p>通过维护牌号工艺标准或生产牌号的原料的检验信息，如烟丝的烘丝温度，接装纸的抗张拉力强度</p><p>通过生产工单和检验标准创建检验工单进行检验，现场使用检查仪器，数采数据通过开发的net桌面程序，通过udp、tcp、opc、串口通信上传至检验工单</p><h3 id="数据采集" tabindex="-1"><a class="header-anchor" href="#数据采集"><span>数据采集</span></a></h3><p>监控数采数据，计算CPK,PPK..质量参数，生成监控图形</p><p>通过创建的工艺标准下发的数采底层系统，PLC通过OPC协议上传至Wonderware数据库，包含牌号，批次，工单号等信息</p><p>通过kafka采集Wonderware数据库的实时数据，并处理计算需要的数据，通过websocket推送至前台展示实时监控图形</p>`,28)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};